def format_rag_prompt(user_query, retrieved_chunks):
    context_block = '\n---\n'.join(retrieved_chunks)
    return f'''Answer the query using ONLY the verified reference context below.
If the context is insufficient, state 'Information not found.'

Reference Context:
{context_block}

User Query: {user_query}
Answer:'''

chunks = ['Q3 revenue reached $14.2M, up 22% year-over-year.']
print(format_rag_prompt('What was our Q3 revenue?', chunks))
